package com.univmar.order.domain;
import com.univmar.catalog.domain.StoneVariant; import com.univmar.shared.domain.BaseEntity; import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="order_items") public class OrderItem extends BaseEntity { @ManyToOne(optional=false) @JoinColumn(name="order_id") private Order order; @ManyToOne @JoinColumn(name="variant_id") private StoneVariant variant; @Column(nullable=false) private String descriptionSnapshot; @Column(nullable=false,precision=19,scale=2) private BigDecimal quantity; @Column(nullable=false,precision=19,scale=2) private BigDecimal unitPrice; @Column(nullable=false,precision=19,scale=2) private BigDecimal lineTotal; protected OrderItem(){} public OrderItem(Order order,StoneVariant variant,String description,BigDecimal quantity,BigDecimal price,BigDecimal lineTotal){this.order=order;this.variant=variant;descriptionSnapshot=description;this.quantity=quantity;unitPrice=price;this.lineTotal=lineTotal;} public StoneVariant getVariant(){return variant;} public BigDecimal getQuantity(){return quantity;} public String getDescriptionSnapshot(){return descriptionSnapshot;} public BigDecimal getUnitPrice(){return unitPrice;} public BigDecimal getLineTotal(){return lineTotal;} }
